<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { getNavigationMenuContext, getNavigationMenuItemContext } from './navigation-menu-context.svelte.js'; interface Props extends Omit<HTMLAttributes<HTMLSpanElement>, 'children'> { children?: Snippet; ref?: HTMLSpanElement | null; } let { children, ref = $bindable(null), ...rest }: Props = $props(); const navigation = getNavigationMenuContext(); const item = getNavigationMenuItemContext();</script><span bind:this={ref} {...rest} aria-hidden="true" data-open={navigation.value === item.value ? '' : undefined}>{@render children?.()}</span>
